```tsx
import type { JSX } from "react";
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;

  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;

  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
}: ButtonRowProps): JSX.Element {
  return (
    <div className="button-row">
      <button
        type="button"
        className="btn primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>
      <button
        type="button"
        className="btn secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>
      <button
        type="button"
        className="btn quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1.2vw, 1rem);
}

.btn {
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.35vw, 1.125rem);
  line-height: 1.2;
  padding: 0.6em 1.25em;
  border-radius: 999px;
  border: 1px solid var(--ink);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease;
}

.btn:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

/* Primary: solid accent fill, text in the page colour (4.57:1 in both themes). */
.btn.primary {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
  font-weight: 600;
}

.btn.primary:not(:disabled):hover {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

/* Secondary: outlined in ink. */
.btn.secondary:not(:disabled):hover {
  background: var(--myelin-wash);
}

/* Quiet: text only, no border or fill. */
.btn.quiet {
  border-color: transparent;
  padding-inline: 0.6em;
  color: var(--muted);
}

.btn.quiet:not(:disabled):hover {
  color: var(--ink);
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
}

:root[data-motion="reduce"] .btn {
  transition: none;
}
```

